fields.InputDefinition:
{
  "goal": "In the Component Studio app (Components section), select a component card so the center workspace loads its editor. In the editor tab bar on the right of the workspace, verify multiple editor tabs render (Spec, Code, Requirements, Design, Data). Click the 'Code' tab and verify the code editor content area displays for that tab (source/code view). If the editor panel is collapsed, use the columns/toggle button in the Preview sub-header to reveal it first. Pages can take 10-30s to load — wait, don't navigate away. Seeing the editor tabs render and the Code tab activate is success.",
  "startUrl": "http://localhost:4200/app/component-studio",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Selecting a component shows an editor tab bar including Spec, Code, Requirements, Design, and Data tabs",
    "Clicking the 'Code' tab activates it and displays the code/source editor content area",
    "No error messages, blank screens, or crash pages"
  ]
}
